register_post_type(
	'wpbp_invoice',
	array(
		'labels'          => array(
			'name'          => 'Invoices',
			'singular_name' => 'Invoice',
		),
		'public'          => false,
		'show_ui'         => true,
		'show_in_rest'    => true,
		'rest_base'       => 'invoices',
		'capability_type' => array( 'invoice', 'invoices' ),
		'map_meta_cap'    => true,
		'supports'        => array( 'title', 'editor', 'author' ),
	)
);

$wpbp_invoice_caps = get_post_type_object( 'wpbp_invoice' )->cap;

// Administrators get every primitive invoice capability.
$wpbp_admin = get_role( 'administrator' );
if ( $wpbp_admin ) {
	foreach ( array( 'edit_posts', 'edit_others_posts', 'edit_private_posts', 'edit_published_posts', 'publish_posts', 'read_private_posts', 'delete_posts', 'delete_others_posts', 'delete_private_posts', 'delete_published_posts' ) as $wpbp_generic ) {
		$wpbp_admin->add_cap( $wpbp_invoice_caps->$wpbp_generic );
	}
}

// Accountants write and edit every invoice, delete their own, never publish.
$wpbp_accountant_caps = array(
	'read'                                      => true,
	$wpbp_invoice_caps->edit_posts             => true,
	$wpbp_invoice_caps->edit_others_posts      => true,
	$wpbp_invoice_caps->edit_published_posts   => true,
	$wpbp_invoice_caps->delete_posts           => true,
	$wpbp_invoice_caps->delete_published_posts => true,
);
$wpbp_accountant = get_role( 'wpbp_accountant' );
if ( ! $wpbp_accountant ) {
	add_role( 'wpbp_accountant', 'Accountant', $wpbp_accountant_caps );
} else {
	foreach ( $wpbp_accountant_caps as $wpbp_cap => $wpbp_grant ) {
		$wpbp_accountant->add_cap( $wpbp_cap, $wpbp_grant );
	}
}

